INSERT INTO public.menu_items
    (category, subcategory, name, description, size_volume, price, notes, available)
SELECT s.category, s.subcategory, s.name, s.description,
       s.size_volume, s.price, s.notes, true
FROM source_menu AS s
WHERE NOT EXISTS (
    SELECT 1
    FROM public.menu_items AS existing
    WHERE existing.category = s.category
      AND existing.name = s.name
      AND existing.subcategory IS NOT DISTINCT FROM s.subcategory
      AND existing.description IS NOT DISTINCT FROM s.description
      AND existing.size_volume IS NOT DISTINCT FROM s.size_volume
)
ORDER BY s.excel_row;

COMMIT;

SELECT category, COUNT(*) AS product_count
FROM public.menu_items
GROUP BY category
ORDER BY category;
